<script setup lang="ts">import { NTag } from 'naive-ui'; import type { AgentTraceRecord } from '@hermes/shared'; defineProps<{ traces: AgentTraceRecord[] }>(); const emit=defineEmits<{select:[traceId:string]}>()</script>
<template><div class="timeline"><button v-for="trace in traces" :key="trace.traceId" type="button" class="trace-row" @click="emit('select', trace.traceId)"><span class="trace-dot" :class="`dot-${trace.status}`"></span><span class="trace-main"><strong>{{ trace.agent }} · {{ trace.phase || '事件' }}</strong><small>{{ trace.message || trace.model || '追踪更新' }}</small></span><NTag size="tiny" :bordered="false">{{ trace.duration ? `${trace.duration}ms` : trace.status }}</NTag></button><div v-if="!traces.length" class="empty">执行追踪事件将在运行时显示。</div></div></template>
<style scoped>.timeline{display:grid;gap:6px}.trace-row{display:flex;align-items:center;gap:10px;width:100%;padding:10px;border:1px solid rgba(148,163,184,.18);border-radius:8px;background:transparent;text-align:left;color:var(--text-primary);cursor:pointer}.trace-row:hover{background:rgba(14,165,233,.06)}.trace-dot{width:8px;height:8px;border-radius:50%;background:#94a3b8}.dot-running{background:#f59e0b;box-shadow:0 0 0 4px rgba(245,158,11,.14)}.dot-success{background:#22c55e}.dot-failed{background:#ef4444}.trace-main{display:grid;gap:3px;flex:1;min-width:0}.trace-main small{color:var(--text-secondary);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.empty{padding:24px;color:var(--text-muted);font-size:12px}</style>
